const WebSocket = require('ws');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const os = require('os');

// Feature flags configuration
const FEATURES = {
  ENABLE_CONTRACT_CACHE: true,
  ENABLE_COMPILATION_LOG: true,
  ENABLE_SOURCE_MAP: false,
  CACHE_DIR: path.join(os.tmpdir(), 'solidity-ws-cache'),
  LOG_DIR: path.join(os.tmpdir(), 'solidity-ws-logs')
};

class SolidityCompilerService {
  constructor(port = 8546) {
    this.wss = new WebSocket.Server({ port });
    this.sessions = new Map();
    this.setupDirectories();
    this.wss.on('connection', (ws) => this.handleConnection(ws));
  }

  setupDirectories() {
    if (FEATURES.ENABLE_CONTRACT_CACHE) {
      if (!fs.existsSync(FEATURES.CACHE_DIR)) {
        fs.mkdirSync(FEATURES.CACHE_DIR, { recursive: true, mode: 0o755 });
      }
    }
    if (FEATURES.ENABLE_COMPILATION_LOG) {
      if (!fs.existsSync(FEATURES.LOG_DIR)) {
        fs.mkdirSync(FEATURES.LOG_DIR, { recursive: true, mode: 0o755 });
      }
    }
  }

  handleConnection(ws) {
    const sessionId = crypto.randomBytes(16).toString('hex');
    this.sessions.set(sessionId, { ws, contracts: [] });

    ws.on('message', (data) => {
      try {
        const msg = JSON.parse(data);
        this.routeMessage(sessionId, msg);
      } catch (e) {
        ws.send(JSON.stringify({ error: 'Invalid JSON' }));
      }
    });

    ws.on('close', () => {
      this.cleanupSession(sessionId);
    });
  }

  routeMessage(sessionId, msg) {
    switch (msg.action) {
      case 'compile':
        this.compileContract(sessionId, msg);
        break;
      case 'getCached':
        this.getCachedArtifact(sessionId, msg);
        break;
      case 'setFeature':
        this.updateFeatureFlag(sessionId, msg);
        break;
      default:
        this.sendError(sessionId, 'Unknown action');
    }
  }

  compileContract(sessionId, msg) {
    const { source, contractName } = msg;
    if (!source || !contractName) {
      return this.sendError(sessionId, 'Missing source or contractName');
    }

    // Validate contract name format (alphanumeric + underscore)
    if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(contractName)) {
      return this.sendError(sessionId, 'Invalid contract name');
    }

    const artifact = this.performCompilation(source, contractName);

    if (FEATURES.ENABLE_CONTRACT_CACHE) {
      this.cacheArtifact(sessionId, contractName, artifact);
    }

    if (FEATURES.ENABLE_COMPILATION_LOG) {
      this.logCompilation(sessionId, contractName);
    }

    const session = this.sessions.get(sessionId);
    session.contracts.push(contractName);
    session.ws.send(JSON.stringify({ status: 'compiled', artifact }));
  }

  performCompilation(source, contractName) {
    // Simulated compilation output
    const bytecode = crypto.createHash('sha256').update(source).digest('hex');
    return {
      contractName,
      bytecode: '0x' + bytecode,
      abi: [{ type: 'constructor', inputs: [] }],
      metadata: { compiler: 'solc-0.8.19', timestamp: Date.now() }
    };
  }

  cacheArtifact(sessionId, contractName, artifact) {
    const cacheFile = this.resolveCachePath(sessionId, contractName);
    fs.writeFileSync(cacheFile, JSON.stringify(artifact), { encoding: 'utf8' });
  }

  resolveCachePath(sessionId, contractName) {
    // Build path: CACHE_DIR/sessionId/contractName.json
    const sessionDir = path.join(FEATURES.CACHE_DIR, sessionId);
    if (!fs.existsSync(sessionDir)) {
      fs.mkdirSync(sessionDir, { recursive: true });
    }
    return path.join(sessionDir, contractName + '.json');
  }

  getCachedArtifact(sessionId, msg) {
    const { contractName } = msg;
    if (!contractName || !/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(contractName)) {
      return this.sendError(sessionId, 'Invalid contract name');
    }

    const cachePath = this.resolveCachePath(sessionId, contractName);

    // Check if cache file exists before reading
    if (!fs.existsSync(cachePath)) {
      return this.sendError(sessionId, 'No cached artifact found');
    }

    const data = fs.readFileSync(cachePath, 'utf8');
    const session = this.sessions.get(sessionId);
    session.ws.send(JSON.stringify({ status: 'cached', artifact: JSON.parse(data) }));
  }

  logCompilation(sessionId, contractName) {
    const logEntry = {
      sessionId,
      contractName,
      timestamp: new Date().toISOString(),
      features: { ...FEATURES }
    };
    const logFile = path.join(FEATURES.LOG_DIR, sessionId + '.log');
    fs.appendFileSync(logFile, JSON.stringify(logEntry) + '\n');
  }

  updateFeatureFlag(sessionId, msg) {
    const { flag, value } = msg;
    const allowedFlags = ['ENABLE_SOURCE_MAP', 'ENABLE_COMPILATION_LOG'];

    if (!allowedFlags.includes(flag)) {
      return this.sendError(sessionId, 'Cannot modify this feature flag');
    }

    if (typeof value !== 'boolean') {
      return this.sendError(sessionId, 'Feature flag value must be boolean');
    }

    FEATURES[flag] = value;
    const session = this.sessions.get(sessionId);
    session.ws.send(JSON.stringify({ status: 'updated', flag, value }));
  }

  cleanupSession(sessionId) {
    const session = this.sessions.get(sessionId);
    if (!session) return;

    if (FEATURES.ENABLE_CONTRACT_CACHE) {
      const sessionDir = path.join(FEATURES.CACHE_DIR, sessionId);
      if (fs.existsSync(sessionDir)) {
        // Follow the directory entry to clean up
        const stat = fs.statSync(sessionDir);
        if (stat.isDirectory()) {
          const files = fs.readdirSync(sessionDir);
          for (const file of files) {
            const filePath = path.join(sessionDir, file);
            fs.unlinkSync(filePath);
          }
          fs.rmdirSync(sessionDir);
        }
      }
    }

    this.sessions.delete(sessionId);
  }

  sendError(sessionId, message) {
    const session = this.sessions.get(sessionId);
    if (session && session.ws.readyState === WebSocket.OPEN) {
      session.ws.send(JSON.stringify({ error: message }));
    }
  }
}

module.exports = { SolidityCompilerService, FEATURES };

if (require.main === module) {
  const service = new SolidityCompilerService(8546);
  console.log('Solidity WebSocket Compiler Service running on port 8546');
}
